import java.util.*;

public class Main {
    public static void main(String[] args) {
        AutocompleteTrie trie = new AutocompleteTrie(3); // cache the top 3 suggestions per node

        // Build the trie from a set of known queries and their aggregated search frequencies.
        trie.insertQuery("how to code", 100);
        trie.insertQuery("hot dog recipe", 95);
        trie.insertQuery("how are you", 90);
        trie.insertQuery("how to cook", 80);
        trie.insertQuery("how to draw", 60);
        trie.insertQuery("how to dance", 40);

        System.out.println("Suggestions for 'h': " + trie.getSuggestions("h"));
        System.out.println("Suggestions for 'ho': " + trie.getSuggestions("ho"));
        System.out.println("Suggestions for 'how': " + trie.getSuggestions("how"));
        System.out.println("Suggestions for 'hot': " + trie.getSuggestions("hot"));
        System.out.println("Suggestions for 'xyz' (never searched): " + trie.getSuggestions("xyz"));

        List<String> hSuggestions = trie.getSuggestions("h");
        List<String> howSuggestions = trie.getSuggestions("how");
        System.out.println("Top suggestion for 'how' is the highest frequency match: " + howSuggestions.get(0).equals("how to code"));
        System.out.println("'hot dog recipe' appears for the broader prefix 'h': " + hSuggestions.contains("hot dog recipe"));
        System.out.println("'hot dog recipe' correctly excluded once the prefix narrows to 'how': " + !howSuggestions.contains("hot dog recipe"));
    }
}

// One node in the trie, caching its own precomputed top suggestions
// so a live query never needs to traverse its descendants.
class TrieNode {
    Map<Character, TrieNode> children = new HashMap<>();       // one child per next character
    List<String> cachedTopSuggestions = new ArrayList<>();         // this node's precomputed top completions
}

// A prefix tree built offline from query frequency data, answering live
// lookups by returning a node's already-computed top suggestions.
class AutocompleteTrie {
    private final TrieNode root = new TrieNode();                          // the empty-prefix starting point
    private final int topK;                                                   // how many suggestions to cache per node
    private final Map<String, Long> queryFrequencies = new HashMap<>();          // query text -> its aggregated frequency

    public AutocompleteTrie(int topK) {
        this.topK = topK; // store how many suggestions each node should cache
    }

    // Called during the offline build, once per known query and its
    // aggregated frequency, inserting it along every prefix of itself.
    public void insertQuery(String query, long frequency) {
        queryFrequencies.put(query, frequency); // remember this query's frequency for ranking
        TrieNode current = root;                   // start walking from the root
        for (char c : query.toCharArray()) {
            current = current.children.computeIfAbsent(c, ch -> new TrieNode()); // create the path as needed
            considerForTopK(current, query, frequency);                             // this node might need to cache this query
        }
    }

    // Keeps a node's cached suggestions sorted by frequency descending,
    // trimmed to the configured top K, recomputed fully during each build.
    private void considerForTopK(TrieNode node, String query, long frequency) {
        if (!node.cachedTopSuggestions.contains(query)) {
            node.cachedTopSuggestions.add(query); // only add once per node, even if inserted multiple times
        }
        node.cachedTopSuggestions.sort((a, b) -> Long.compare(frequencyOf(b), frequencyOf(a))); // highest frequency first
        if (node.cachedTopSuggestions.size() > topK) {
            node.cachedTopSuggestions = new ArrayList<>(node.cachedTopSuggestions.subList(0, topK)); // trim to top K
        }
    }

    private long frequencyOf(String query) {
        return queryFrequencies.getOrDefault(query, 0L); // this query's known frequency, zero if somehow unknown
    }

    // Called live, on every keystroke, walking down to the node for this
    // exact prefix and returning whatever is already cached there.
    public List<String> getSuggestions(String prefix) {
        TrieNode current = root;                    // start walking from the root
        for (char c : prefix.toCharArray()) {
            current = current.children.get(c);          // follow this character's path
            if (current == null) {
                return Collections.emptyList(); // this prefix has never been searched
            }
        }
        return current.cachedTopSuggestions; // already precomputed, no work left to do
    }
