#include <algorithm>
#include <iostream>
#include <map>
#include <string>
#include <vector>

// One node in the trie, caching its own precomputed top suggestions
// so a live query never needs to traverse its descendants.
struct TrieNode {
    std::map<char, TrieNode*> children;              // one child per next character
    std::vector<std::string> cachedTopSuggestions;      // this node's precomputed top completions
};

std::string formatList(const std::vector<std::string>& items) {
    std::string s = "[";
    for (size_t i = 0; i < items.size(); i++) {
        if (i) s += ", ";
        s += items[i];
    }
    s += "]";
    return s;
}

// A prefix tree built offline from query frequency data, answering live
// lookups by returning a node's already-computed top suggestions.
class AutocompleteTrie {
public:
    explicit AutocompleteTrie(int topK) : root_(new TrieNode()), topK_(topK) {}

    // Called during the offline build, once per known query and its
    // aggregated frequency, inserting it along every prefix of itself.
    void insertQuery(const std::string& query, long frequency) {
        queryFrequencies_[query] = frequency;   // remember this query's frequency for ranking
        TrieNode* current = root_;                 // start walking from the root
        for (char c : query) {
            if (current->children.find(c) == current->children.end()) {
                current->children[c] = new TrieNode();   // create the path as needed
            }
            current = current->children[c];
            considerForTopK(current, query);            // this node might need to cache this query
        }
    }

    // Called live, on every keystroke, walking down to the node for this
    // exact prefix and returning whatever is already cached there.
    std::vector<std::string> getSuggestions(const std::string& prefix) {
        TrieNode* current = root_;                  // start walking from the root
        for (char c : prefix) {
            auto it = current->children.find(c);       // follow this character's path
            if (it == current->children.end()) {
                return {};   // this prefix has never been searched
            }
            current = it->second;
        }
        return current->cachedTopSuggestions;   // already precomputed, no work left to do
    }

private:
    // Keeps a node's cached suggestions sorted by frequency descending,
    // trimmed to the configured top K, recomputed fully during each build.
    void considerForTopK(TrieNode* node, const std::string& query) {
        if (std::find(node->cachedTopSuggestions.begin(), node->cachedTopSuggestions.end(), query)
            == node->cachedTopSuggestions.end()) {
            node->cachedTopSuggestions.push_back(query);   // only add once per node, even if inserted multiple times
        }
        std::stable_sort(node->cachedTopSuggestions.begin(), node->cachedTopSuggestions.end(),
                          [this](const std::string& a, const std::string& b) { return frequencyOf(a) > frequencyOf(b); });   // highest frequency first
        if (static_cast<int>(node->cachedTopSuggestions.size()) > topK_) {
            node->cachedTopSuggestions.resize(topK_);   // trim to top K
        }
    }

    long frequencyOf(const std::string& query) {
        auto it = queryFrequencies_.find(query);
        return it != queryFrequencies_.end() ? it->second : 0;   // this query's known frequency, zero if somehow unknown
    }

    TrieNode* root_;                                  // the empty-prefix starting point
    int topK_;                                            // how many suggestions to cache per node
    std::map<std::string, long> queryFrequencies_;            // query text -> its aggregated frequency
};

int main() {
    std::cout << std::boolalpha;
    AutocompleteTrie trie(3);   // cache the top 3 suggestions per node

    // Build the trie from a set of known queries and their aggregated search frequencies.
    trie.insertQuery("how to code", 100);
    trie.insertQuery("hot dog recipe", 95);
    trie.insertQuery("how are you", 90);
    trie.insertQuery("how to cook", 80);
    trie.insertQuery("how to draw", 60);
    trie.insertQuery("how to dance", 40);

    std::cout << "Suggestions for 'h': " << formatList(trie.getSuggestions("h")) << "\n";
    std::cout << "Suggestions for 'ho': " << formatList(trie.getSuggestions("ho")) << "\n";
    std::cout << "Suggestions for 'how': " << formatList(trie.getSuggestions("how")) << "\n";
    std::cout << "Suggestions for 'hot': " << formatList(trie.getSuggestions("hot")) << "\n";
    std::cout << "Suggestions for 'xyz' (never searched): " << formatList(trie.getSuggestions("xyz")) << "\n";

    auto hSuggestions = trie.getSuggestions("h");
    auto howSuggestions = trie.getSuggestions("how");
    std::cout << "Top suggestion for 'how' is the highest frequency match: " << (howSuggestions[0] == "how to code") << "\n";
    bool hContains = std::find(hSuggestions.begin(), hSuggestions.end(), "hot dog recipe") != hSuggestions.end();
    std::cout << "'hot dog recipe' appears for the broader prefix 'h': " << hContains << "\n";
    bool howContains = std::find(howSuggestions.begin(), howSuggestions.end(), "hot dog recipe") != howSuggestions.end();
    std::cout << "'hot dog recipe' correctly excluded once the prefix narrows to 'how': " << !howContains << "\n";
    return 0;
}

